"""Evaluate conditional label randomization with exact and binned token masses."""

from collections import Counter, defaultdict
from concurrent.futures import ProcessPoolExecutor
from dataclasses import dataclass
from itertools import product
import json
from math import factorial, prod
from pathlib import Path
import random
import re
import sys

import numpy as np
from vs import corpus, dsl, redteam


ROOT = Path(__file__).resolve().parent
PRIOR = ROOT.parent / "voynich-section-null-work"
sys.path.insert(0, str(PRIOR))
from calibrate_sections import MarginTest, SELECT, assign, describe_layout, intervention
from stationary import Writer, learn


PLAN = json.loads((ROOT / "matched-null-plan.json").read_text())


@dataclass
class Draws:
    alternatives: list
    metadata: dict


def count_vectors(labels, blocks):
    return prod(
        factorial(len(block)) // prod(factorial(value) for value in Counter(labels[block]).values())
        for block in blocks
    )


def distinct_orders(values):
    counts = Counter(int(value) for value in values)
    keys = sorted(counts)
    prefix = []

    def extend():
        if len(prefix) == len(values):
            yield tuple(prefix)
            return
        for key in keys:
            if counts[key]:
                counts[key] -= 1
                prefix.append(key)
                yield from extend()
                prefix.pop()
                counts[key] += 1

    return extend()


def exact_vectors(labels, blocks):
    candidate = labels.copy()
    for ordering in product(*(distinct_orders(labels[block]) for block in blocks)):
        for block, block_labels in zip(blocks, ordering, strict=True):
            candidate[block] = block_labels
        yield candidate.copy()


def proposal_batch(labels, blocks, rng, size):
    result = np.broadcast_to(labels, (size, len(labels))).copy()
    for block in blocks:
        if len(set(labels[block])) > 1:
            indices = np.argsort(rng.random((size, len(block))), axis=1)
            result[:, block] = labels[block][indices]
    return result


def group_mass(label_rows, weights, sections):
    offset = sections * np.arange(len(label_rows))[:, None]
    packed = (label_rows + offset).ravel()
    return np.bincount(
        packed, weights=np.tile(weights, len(label_rows)), minlength=len(label_rows) * sections
    ).astype(np.int64).reshape(-1, sections)


def alternatives(labels, weights, blocks, seed, binned):
    sections = int(labels.max()) + 1
    original = group_mass(labels[None, :], weights, sections)[0]
    total = weights.sum()
    target = 100 * original // total if binned else original
    ceiling = PLAN["proposal_cap"]
    sample_size = PLAN["max_distinct_nonidentity"]
    ambient = count_vectors(labels, blocks)
    rng = np.random.default_rng(seed)
    exact = ambient <= ceiling
    picked = []
    signatures = {labels.tobytes()}
    proposals = 0
    accepted_with_repetitions = 0
    if exact:
        candidates = np.array(list(exact_vectors(labels, blocks)))
        assignments = [candidates]
    else:
        assignments = (proposal_batch(labels, blocks, rng, min(256, ceiling - start))
                       for start in range(0, ceiling, 256))
    exhausted = True
    for batch in assignments:
        masses = group_mass(batch, weights, sections)
        outcomes = 100 * masses // total if binned else masses
        for index, candidate in enumerate(batch):
            proposals += 1
            if not np.array_equal(outcomes[index], target):
                continue
            accepted_with_repetitions += 1
            signature = candidate.tobytes()
            if signature in signatures:
                continue
            signatures.add(signature)
            picked.append(candidate.copy())
            if not exact and len(picked) == sample_size:
                exhausted = False
                break
        if not exhausted:
            break
    known = len(picked) + 1 if exact else None
    if len(picked) > sample_size:
        picked = [picked[i] for i in rng.choice(len(picked), size=sample_size, replace=False)]
    picked_mass = group_mass(np.asarray(picked), weights, sections) if picked else np.empty((0, sections))
    shift = int(np.max(np.abs(picked_mass - original))) if picked else 0
    moved = [int(np.count_nonzero(candidate != labels)) for candidate in picked]
    return Draws(picked, {
        "ambient_distinct_including_identity": str(ambient),
        "exact_conditioned_support_including_identity": known,
        "retained_nonidentity": len(picked), "inspected_proposals": proposals,
        "accepted_proposals_including_repetitions": accepted_with_repetitions,
        "largest_section_word_count_shift": shift,
        "minimum_moved_pages": min(moved, default=0), "maximum_moved_pages": max(moved, default=0),
    })


def construct(layout, page_ids, selected, names, seed):
    labels = np.array([names.index(section) for section in layout.page_labels])
    weights = np.bincount(page_ids[selected], minlength=len(labels))
    by_count = defaultdict(list)
    for index, count in enumerate(weights):
        by_count[int(count)].append(index)
    exact_blocks = [np.array(indices) for _, indices in sorted(by_count.items())]
    def page_number(index):
        match = re.fullmatch(r"f(\d+)([rv])(\d*)", layout.report["page_ids"][index])
        return int(match[1]), match[2], int(match[3] or 0)
    ranks = sorted(range(len(labels)), key=lambda index: (weights[index], page_number(index)))
    interval = PLAN["rank_block_size"]
    rank_blocks = [np.array(ranks[start:start + interval]) for start in range(0, len(ranks), interval)]
    return (
        alternatives(labels, weights, exact_blocks, PLAN["equal_count_null_seed_offset"] + seed, False),
        alternatives(labels, weights, rank_blocks, PLAN["binned_null_seed_offset"] + seed, True),
    )


def prepare():
    train, _ = corpus.split_pages("practice", "zl")
    eligible = [page for page in train if dsl.select(dsl.tokens([page]), SELECT)]
    reserved = random.Random(408).sample(eligible, max(PLAN["sizes"]))
    held_ids = {page.id for page in reserved}
    fitting = [page for page in train if page.id not in held_ids]
    layouts = []
    for size in PLAN["sizes"]:
        manuscript = sorted(reserved[:size], key=lambda page: page.order)
        layouts.append(describe_layout(manuscript, "manuscript"))
        for seed in PLAN["additional_page_order_seeds"]:
            pages = list(manuscript)
            random.Random(seed + size).shuffle(pages)
            layouts.append(describe_layout(pages, f"shuffle-{seed}"))
    assert len(fitting) == 68
    return layouts, learn(fitting), redteam._manuscript_4grams()


def target_rank(test, sample, draws, observed):
    words = sample[test.selected]
    word_mass = test.mass(np.bincount(words))
    tie_threshold = observed - 1e-11
    return 1 + sum(
        test.value(words, labels, word_mass, section_mass) >= tie_threshold
        for labels, section_mass in draws
    )


def run(seed):
    layouts, contexts, forbidden = PREPARED
    support = []
    rows = []
    shared = {}
    for layout in layouts:
        if layout.size not in shared:
            writer = Writer(contexts, seed, forbidden)
            mixture = random.Random(seed + 8192)
            proportion = sum(item[3] for item in layout.items) / len(layout.items)
            shared[layout.size] = [writer.line(mixture.random() < proportion) for _ in layout.items]
        words, page_ids, selected = assign(layout, "one shared", ([], [], shared))
        names = sorted(set(layout.page_labels))
        indices = [names.index(section) for section in layout.page_labels]
        standard = MarginTest(page_ids, selected, indices, seed)
        exact, binned = construct(layout, page_ids, selected, names, seed)
        support.append([seed, layout.size, layout.order, exact.metadata, binned.metadata])
        matched = [
            [(pages[standard.page_ids], standard.mass(np.bincount(pages[standard.page_ids])))
             for pages in draws.alternatives]
            for draws in (exact, binned)
        ]
        cases = [("base", 0, words)]
        for dose, plant, placebo in intervention(words, page_ids, selected, indices, seed, layout.size):
            cases.extend([("plant", dose, plant), ("placebo", dose, placebo)])
        for name, dose, sample in cases:
            vocabulary = {word: i for i, word in enumerate(dict.fromkeys(sample))}
            encoded = np.fromiter((vocabulary[word] for word in sample), dtype=np.int64, count=len(sample))
            selected_words = encoded[standard.selected]
            observed = standard.value(
                selected_words, standard.observed, standard.mass(np.bincount(selected_words)), standard.fixed_section_mass
            )
            common_scores = standard.score(encoded)
            rows.append([seed, layout.size, layout.order, name, dose, *common_scores,
                         *[int(target_rank(standard, encoded, draws, observed)) for draws in matched],
                         len(exact.alternatives), len(binned.alternatives)])
    return {"support": support, "cases": rows}


PREPARED = None


def main():
    global PREPARED
    PREPARED = prepare()
    (ROOT / "layouts.json").write_text(json.dumps([layout.report for layout in PREPARED[0]], indent=2) + "\n")
    seeds = PLAN["background_seeds"] if len(sys.argv) == 1 else [int(value) for value in sys.argv[1:]]
    with ProcessPoolExecutor(max_workers=min(7, len(seeds))) as executor:
        for seed, results in zip(seeds, executor.map(run, seeds), strict=True):
            print(json.dumps(results, separators=(",", ":")), flush=True)
            print(f"completed seed {seed} ({len(results['cases'])} cases)", file=sys.stderr, flush=True)


if __name__ == "__main__":
    main()
